// ============================================================
//  The era pack: Korea's Three Kingdoms (삼국시대), c. 1 - 668.
//
//  Goguryeo (고구려), Baekje (백제), Silla (신라) and the Gaya (가야)
//  confederacy contend for the peninsula and southern Manchuria. Like every
//  era pack, this folder is all the engine needs: era.js (this manifest),
//  data.js (map, houses, officers, titles, scenarios), events.js (history),
//  geo.js and hexmaps.js (generated by tools/ from public-domain data).
//  The engine in js/ knows no names or dates; it reads this object.
// ============================================================
const ERA = {
  id: 'samguk',
  title: '삼국시대 — Korea’s Three Kingdoms',
  sigil: '三國',
  blurb: '한(漢)의 변방에서 세 나라가 일어선다. 한반도를 통일하라.',

  // where this era's generated pictures live
  assets: {
    relief: 'img/eras/samguk/relief.png',
    hex: 'img/eras/samguk/hex/',
    // Drop an <officer name>.png here (e.g. 김유신.png) and it shows as a
    // portrait; otherwise a faction-coloured initial avatar stands in.
    portraits: 'img/eras/samguk/officers/',
  },

  // The map window: equirectangular projection shared by the game and by
  // tools/buildmap.js, buildrelief.js, buildhex.js, which generate from it.
  //   project(lon,lat) = [(lon - lon0) * kx, (lat1 - lat) * ky]
  // Window spans lon [122, 132]E, lat [33, 44]N: the Korean peninsula plus
  // Liaodong / southern Manchuria (Goguryeo's reach), with Jeju at the foot.
  map: { W: 950, H: 1045, lon0: 122, lat1: 44, kx: 95, ky: 95 },

  rules: {
    // champions ride out to call each other to single combat
    duels: true,
    // how a walled city is broken: 'gates' (rams at the wall) or 'artillery'
    siege: 'gates',
    // a court that grants ranks and titles to its officers
    titles: true,
    // the prize that lends legitimacy: whoever holds it recruits, treats and
    // taxes better. For Korea the prize is the old royal capital that confers
    // the mantle of the senior kingdom; data.js names the city that grants it.
    legitimacy: { enabled: true, label: '정통(正統)' },
  },

  // Map decorations drawn by js/terrain.js: [text, lon, lat, rotation, size].
  // No wall/steppe here (an empty wall/steppe draws nothing); labels sit
  // inside this era's window (lon 122-132E, lat 33-44N).
  decor: {
    labels: [
      ['서해', 124.3, 36.8, 0, 15],
      ['동해', 130.4, 37.6, 0, 15],
      ['남해', 127.3, 34.1, 0, 13],
      ['압록강', 127.0, 40.6, 30, 10],
      ['두만강', 129.9, 42.4, 20, 10],
      ['한강', 127.4, 37.7, 8, 10],
      ['낙동강', 128.1, 35.9, 70, 10],
      ['백두산', 128.05, 41.99, 0, 10],
      ['요동', 123.2, 41.0, 0, 10],
      ['탐라', 126.5, 33.4, 0, 8],
    ],
  },
};
